// steers a moby along a path using its velocity and returns a status code
int move_hoven_anklebiter_toward_heading(char *moby, float target) {
    float pos[4];
    float vel[4];
    float out[4];
    float res[4];
    float k = 0.05f;
    float w[4];
    float v[4];
    struct HovenTrollVars *d;
    int r;
    d = (struct HovenTrollVars *)((Moby *)moby)->pvars;
    *(u128 *)pos = *(u128 *)(moby + 0x10);
    ease_hoven_anklebiter_height_to_ground(moby);
    MobySpringTurn(moby, &d->turn_vel, target, k, 0.3f, 0.2f);
    vel[0] = FastCos(((Moby *)moby)->rot.z) * 2;
    vel[1] = FastSin(((Moby *)moby)->rot.z) * 2;
    vel[2] = 0;
    r = MobySteerToward(moby, d->move_ctl, vel, (char *)out, 1.0f);
    if (d->path_index != -1) {
        float *vp = v;
        FastVecSub(vp, pos, moby + 0x10);
        vec_scale_to_length(vp, vp, k);
        FastVecAdd(w, pos, vp);
        if (path_8808(d->path_index, moby + 0x10, w, res)) {
            int *tbl = (int *)l12_paths[d->path_index];
            if (point_in_path_xy(moby + 0x10, tbl + 4, *tbl) == 0) {
                *(u128 *)(moby + 0x10) = *(u128 *)res;
            }
            if (fast_vec_dist(moby + 0x10, pos) < g_frame_time * 0.5f) {
                d->stuck_ticks = d->stuck_ticks + 1;
                if (scale_ticks(10) < d->stuck_ticks)
                    r = 2;
            } else {
                d->stuck_ticks = 0;
            }
        }
    }
    return r;
}
