/* Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l12/gameplay/entities/002bf140.c, FUN_L12_002e3c08. */
void steer_platform_toward_target(Moby *m, float *ang, void *target, int unused, int brake) {
    struct HovenPlatformVars *d = (struct HovenPlatformVars *)m->pvars;
    float v[4];
    float dist;
    float speed;
    float acc;
    float lim = 1.9198622f;
    FastVecSub(v, target, &m->pos);
    dist = FastVecLength(v);
    speed = FastVecLength(&d->vel);
    if (brake) {
        if (speed == 0.0f)
            speed = g_frame_time * 0.01f;
        acc = d->accel * g_frame_time_sq;
        if (acc < speed * speed / (dist + dist))
            speed -= acc;
        else if (speed < d->max_speed * g_frame_time)
            speed += acc;
    } else {
        if (speed < d->max_speed * g_frame_time)
            speed += d->accel * g_frame_time_sq;
        else if (d->max_speed * g_frame_time < speed)
            speed -= d->accel * g_frame_time_sq;
    }
    vec_scale_to_length(&d->vel, v, speed);
    ApproachValue(&m->rot, ang[0], FastDiffRots(ang[0], m->rot.x) / (platform_tilt_approach_divisor));
    ApproachValue(&m->rot.y, ang[1], FastDiffRots(ang[1], m->rot.y) / (platform_tilt_approach_divisor));
    spring_angle(&m->rot.z, ang[2], &d->yaw_vel, 0, g_frame_scale_sq * 0.005f, g_frame_scale_sq * 0.3f,
                 g_frame_time * lim);
    FastVecAdd(&m->pos, &m->pos, &d->vel);
}
