/* Projects a moby's offset from a reference point into a 2D pair, or zeroes it. */
void compute_platform_target_tilt(char *moby, float *out, int on) {
    float m[4];
    float a[4];
    float b[4];
    float pad[12];
    float g;
    if (on) {
        FastVecSub(a, &g_hero.motion.pos, moby + 0x10);
        clear_u64_value(m);
        m[2] = -*(float *)(moby + 0x48);
        euler_to_matrix(b, m);
        transform_vector(a, a, b);
        g = platform_tilt_offset_divisor;
        out[1] = a[0] / g;
        out[0] = -a[1] / g;
    } else {
        out[0] = 0;
        out[1] = 0;
    }
}
