/* Miner update on level 12: runs its conversation states, steers its body and head toward the player and keeps its
   helper moby attached. */
void miner_update(Moby *m) {
    Scratch scratch;
    Data_2E7FC8 *d = (Data_2E7FC8 *)m->pvars;
    float rate;
    float head_rate;
    int tracking;
    apply_npc_big_head_cheat((char *)m);
    switch (m->state) {
        case 0:
            if (((Flags *)gSpecialItems)->f1 != 0) {
                DeleteMoby(m);
                return;
            }
            m->state = 1;
            DialogRequest_Init(m, d->activation);
            initialize_moby_grounding(m);
            break;
        case 1:
            if (((Flags *)gSpecialItems)->f1 == 0 && Npc_TryStartDialog(m, d->activation)) {
                begin_dialogue_camera_transition(2.5f, m);
                m->anim_speed = 0.0f;
                m->state = 2;
            }
            break;
        case 2:
            if (*(int *)&hoven_cinematic_mode_r != 2) {
                Flags *flags = (Flags *)gSpecialItems;
                m->anim_speed = 1.0f;
                flags->f1 = 1;
                queue_dialogue_message(0x2EE7, scale_ticks(300));
                flags->f61 = 1;
                jet_clear_persistent(m->mission);
                if (d->node != -1) {
                    char *t = hoven_camera_points + (d->node << 7);
                    jet_reset_camera(t + 0x30, t + 0x70);
                }
                memcard_Save(0, -1);
                m->state = 1;
            }
            break;
    }
    rate = 0.02f;
    head_rate = 0.3f;
    tracking = 0;
    if (m->prev_seq == 0) {
        char *player = &((struct Hero *)((char *)&hero_globals_base_r2 + 0xE1D))->motion.pos;
        tracking = 1;
        if (vec_distance_xy(&m->pos, player) < 8.0f &&
            FastDiffRots(m->rot.z, fast_atan2(((Player *)((char *)&hero_globals_base_r2 + 0xE1D))->aim[0] - m->pos.x,
                                              ((Player *)((char *)&hero_globals_base_r2 + 0xE1D))->aim[1] - m->pos.y)) <
                1.5707964f) {
            if (FastVecLength(player + 0x80) > 0.01f)
                d->moving_timer = scale_ticks(120);
            else
                fast_dec_timer(&d->moving_timer);
        } else if (d->moving_timer) {
            d->moving_timer = 0;
            qcopy(d->target, &((struct Hero *)((char *)&hero_globals_base_r2 + 0xE1D))->motion.body_center);
        }
        if (fast_dec_timer(&d->target_timer)) {
            float heading;
            d->target_timer = truncate_float_to_s32_r(multiply_global_factor(random_float_between(180.0f, 300.0f)));
            heading = FastAddRots(m->rot.z, random_float_between(-90.0f, 90.0f) * 0.017453292f);
            BuildSphericalOffset(d->target, 6.0f, heading, random_float_between(0.0f, 30.0f) * 0.017453292f);
            FastVecAdd(d->target, d->target, &m->pos);
        }
        if (d->moving_timer) {
            qcopy(scratch.target, &((struct Hero *)((char *)&hero_globals_base_r2 + 0xE1D))->motion.body_center);
            rate = 0.04f;
            head_rate = 0.3f;
        } else {
            qcopy(scratch.target, d->target);
        }
    }
    if (tracking) {
        float yaw;
        float pitch;
        qcopy(scratch.eye, &m->pos);
        scratch.eye[2] += 1.0f;
        FastVecSub(scratch.delta, scratch.target, scratch.eye);
        yaw = FastSubRots(fast_atan2(scratch.delta[0], scratch.delta[1]), m->rot.z);
        pitch = -fast_atan2(vector_length_xy(scratch.delta), scratch.delta[2]);
        if (yaw > 1.5707964f)
            yaw = 1.5707964f;
        else if (yaw < -1.5707964f)
            yaw = -1.5707964f;
        if (pitch > 0.5235988f)
            pitch = 0.5235988f;
        else if (pitch < -0.5235988f)
            pitch = -0.5235988f;
        d->pitch = pitch;
        d->yaw = yaw * 0.3f;
        d->head_yaw = yaw * 0.7f;
    }
    if (gCheats[0])
        d->height = 2.75f;
    EaseManipulatorOffsets_r2(rate * g_frame_scale_sq, head_rate * g_frame_scale_sq, m, d->body, 1);
    EaseManipulatorOffsets_r2(rate * g_frame_scale_sq, head_rate * g_frame_scale_sq, m, d->head, 0);
    if (d->helper == 0) {
        d->helper = CreateMoby_r(0x11F);
        if (d->helper != 0) {
            Moby *h;
            d->helper->draw_dist = (*(unsigned short *)&m->draw_dist);
            d->helper->visible = 1;
            h = d->helper;
            qcopy(&h->pos, &m->pos);
            qcopy(&h->rot, &m->rot);
            moby_build_matrix(m);
        }
    } else {
        update_moby_bone_attachment(m, d->helper, 2);
    }
}

