void set_blarg_trooper_aim_yaw_offsets(char *moby, float *pos) {
    struct Moby *m = (struct Moby *)moby;
    struct SetBlargTrooperAimYawOffsetsVars *data = (struct SetBlargTrooperAimYawOffsetsVars *)m->pvars;
    float target_yaw = fast_atan2(pos[0] - m->pos.x, pos[1] - m->pos.y);
    float yaw_offset = FastSubRots(target_yaw, m->rot.z);
    if (yaw_offset > 1.2217305f) {
        yaw_offset = 1.2217305f;
    } else if (yaw_offset < -1.2217305f) {
        yaw_offset = -1.2217305f;
    }
    data->unk_188 = yaw_offset * 0.35f;
    data->unk_208 = yaw_offset * 0.8f;
}
typedef struct {
    char pad0[0x248];
    void *child;
} Level12VendorData;

/* Release the vendor moby and any child it owns. */
void remove_blarg_trooper_and_attachment(Moby *moby) {
    moby->unkB4 = 0;
    SetDeathBits(moby, 0, -1);
    if (((Level12VendorData *)moby->pvars)->child != 0) {
        DeleteMoby(((Level12VendorData *)moby->pvars)->child);
    }
    DeleteMoby(moby);
}

/* Keeps the Blarg trooper's attachment on its bone, spawning it if missing. */
void update_blarg_trooper_attachment(unsigned char *moby) {
    struct BlargTrooperVars *data = (struct BlargTrooperVars *)((char *)((Moby *)moby)->pvars);
    unsigned char *target = *(unsigned char **)&data->attachment;
    if (target != 0) {
        unsigned char *current;
        update_moby_bone_attachment(moby, target, 1);
        current = *(unsigned char **)&data->attachment;
        if (((Moby *)moby)->flags & 1) {
            *(unsigned short *)(current + 0x34) |= 0x41;
        } else {
            *(unsigned short *)(current + 0x34) &= 0xFFBE;
        }
    } else {
        char vector[16];
        moby_point_position(moby, 1, vector);
        *(void **)&data->attachment = spawn_moby_attachment(moby, vector);
    }
}

